import{z as E,x as A,o as n,c as p,q as t,j as l,D as e,d as r,s as i,S as s}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"堆排序","description":"","frontmatter":{"title":"堆排序","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/heapsort.md","filePath":"cs/heapsort.md","lastUpdated":1791063341000}'),B={name:"cs/heapsort.md"};function h(d,a,m,c,_,T){const o=A("Mermaid");return n(),p("div",null,[a[2]||(a[2]=t('<h1 id="堆排序" tabindex="-1">堆排序 <a class="header-anchor" href="#堆排序" aria-label="Permalink to &quot;堆排序&quot;">​</a></h1><div class="epigraph"><p>堆把无序数组收成可反复取出极值的结构；排序就是建堆再反复弹出。</p><footer>—— 据 Williams, Algorithm 232: Heapsort, 1964；Floyd, Algorithm 245: Treesort 3, 1964；Knuth, TAOCP vol. 3 整理</footer></div><p>上一课<a href="/cs/insertion-merge">插入与归并</a>对照了前缀不变式与分治合并：一个最坏平方、一个最坏 \\(n\\log n\\) 但要线性缓冲。<a href="/cs/insertion-merge">堆与优先队列</a>已经能 \\(O(\\log n)\\) 取出最大元。本课不重建堆。缺口是：用同一数组上的堆完成就地排序，把「额外线性空间」从 \\(n\\log n\\) 比较排序里拿掉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>归并的 \\(\\Theta(n\\log n)\\) 来自分治加线性合并，不是来自堆。若只反复从无序数组找最大再放到末尾，每轮扫描仍是平方。缺口因此不是新的比较模型，而是把已有的堆操作排成：<strong>建堆一次，再把根与未排序后缀的末元对换并下滤</strong>。终止时后缀从大到小填满，整表有序。</p><p>本课仍在比较排序里。稳定性默认放弃：相等键在下滤时可以越过彼此。线性时间排序是后课才离开比较模型。</p><h3 id="建堆不是-次插入" tabindex="-1">建堆不是 \\(n\\) 次插入 <a class="header-anchor" href="#建堆不是-次插入" aria-label="Permalink to &quot;建堆不是 $n$ 次插入&quot;">​</a></h3><p>从空堆插入 \\(n\\) 个是 \\(\\Theta(n\\log n)\\)。Floyd 自底向上：叶子已是堆，从最后一个非叶往根下滤，总代价 \\(\\Theta(n)\\)。排序阶段仍是 \\(n\\) 次 \\(\\Theta(\\log n)\\) 下滤，整体 \\(\\Theta(n\\log n)\\)。不要把建堆也写成 \\(n\\log n\\) 再加一遍。</p><p><span class="marginnote">数字实例：\\(n=15\\)、三层高的完全树只有 7 个非叶：4 个节点最多下滤 1 层、2 个下滤 2 层、1 个下滤 3 层，合计 \\(4\\times1+2\\times2+1\\times3=11\\) 次下沉——随 \\(n\\) 线性。逐个插入则每个都可能爬满 \\(\\log n\\) 层，合计 \\(n\\log n\\)。</span></p><p><span class="marginnote">Williams 给出堆排序；Floyd 把建堆收成线性。Knuth vol. 3 把同一数组既当堆又当输出区。优先队列课已有下滤，本课只排工序。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数组下标堆：父 \\(i\\) 的子为 \\(2i\\)、\\(2i+1\\)（或 \\(0\\) 基等价）。建堆后不变式：下标 \\(1..i\\) 是堆， \\(i+1..n\\) 是已就位的后缀且不小于堆中任何键。每轮：交换 \\(A[1]\\) 与 \\(A[i]\\)， \\(i\\leftarrow i-1\\)，对根下滤。</p>',12)),(n(),l(s,null,{default:e(()=>[i(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%97%A0%E5%BA%8F%E6%95%B0%E7%BB%84%22%5D%20--%3E%20BUILD%5B%22%E8%87%AA%E5%BA%95%E5%90%91%E4%B8%8A%E5%BB%BA%E5%A0%86%20%CE%98(n)%22%5D%0A%20%20BUILD%20--%3E%20SWAP%5B%22%E6%A0%B9%E4%B8%8E%E6%9C%AA%E6%8E%92%E5%BA%8F%E6%9C%AB%E5%85%83%E5%AF%B9%E6%8D%A2%22%5D%0A%20%20SWAP%20--%3E%20SIFT%5B%22%E4%B8%8B%E6%BB%A4%22%5D%0A%20%20SIFT%20--%3E%20DONE%5B%22%E5%90%8E%E7%BC%80%E5%B7%B2%E5%B0%B1%E4%BD%8D%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>正确性走<a href="/cs/loop-invariant">循环不变式</a>：后缀有序且是全局最大的那些键。代价：建堆线性，排序阶段 \\(\\Theta(n\\log n)\\)。</p><p><span class="marginnote">直觉类比：排序阶段像从日历上撕页——每轮把当前最大（根）与未排序末位对调，末位从此「定格」退出堆。数组两头分化：前段还是堆，后段按从小到大一页页长出来。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>就地：只占 \\(O(1)\\) 额外字（递归下滤可改成循环）。与归并对照：最坏同样 \\(n\\log n\\)，空间从 \\(\\Theta(n)\\) 降到常数，缓存上连续下滤与归并的顺序扫描不同，本课不量化。<a href="/cs/locality-principle">局部性</a>只提醒：堆不是顺序扫描。</p><p>下滤破坏稳定性。若要稳定的 \\(n\\log n\\) 就地，本课不提供；那不是堆的职责。</p><p>同是最坏 \\(n\\log n\\)，堆排与归并各让了什么：</p>',6)),(n(),l(s,null,{default:e(()=>[i(o,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%A6%81%E6%9C%80%E5%9D%8F%20n%20log%20n%22%5D%20--%3E%20HS%5B%22%E5%A0%86%E6%8E%92%E5%BA%8F%22%5D%0A%20%20HS%20--%3E%20H1%5B%22%E9%A2%9D%E5%A4%96%E7%A9%BA%E9%97%B4%20O(1)%22%5D%0A%20%20HS%20--%3E%20H2%5B%22%E4%B8%8D%E7%A8%B3%E5%AE%9A%2C%20%E4%B8%8B%E6%BB%A4%E8%B7%B3%E8%B7%83%E8%AE%BF%E5%AD%98%22%5D%0A%20%20Q%20--%3E%20MG%5B%22%E5%BD%92%E5%B9%B6%E6%8E%92%E5%BA%8F%22%5D%0A%20%20MG%20--%3E%20M1%5B%22%E9%A2%9D%E5%A4%96%E7%A9%BA%E9%97%B4%20%CE%98(n)%22%5D%0A%20%20MG%20--%3E%20M2%5B%22%E7%A8%B3%E5%AE%9A%2C%20%E9%A1%BA%E5%BA%8F%E6%89%AB%E6%8F%8F%E7%BC%93%E5%AD%98%E5%8F%8B%E5%A5%BD%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">常见误区：初学者容易以为「堆排最坏 \\(n\\log n\\)、快排期望 \\(n\\log n\\)，那永远选堆排」。实际下滤在数组里大步跳跃（\\(i\\to 2i\\)），缓存命中率差；快排分区是顺序扫描，机器常数常让快排更快。渐近与缓存两层账都要看。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入快排分区，不证比较下界。键不是数轴上的计数对象。图算法里的优先队列仍用堆，但那是松弛不是排序——<a href="/cs/dijkstra">Dijkstra</a>才接。</p><p>后课默认：堆排序 = 线性建堆 + \\(n\\) 次下滤，最坏 \\(\\Theta(n\\log n)\\)，就地、不稳定。期望线性的分区是下一课的缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>堆排序把优先队列变成就地比较排序，最坏 \\(n\\log n\\)。</li><li>建堆 \\(\\Theta(n)\\)；不要写成 \\(n\\) 次插入。</li><li>默认不稳定；额外空间常数。</li><li>出处：Williams, 1964；Floyd, 1964；Knuth, TAOCP vol. 3；CLRS 第 6 章。</li></ul>',6))])}const f=E(B,[["render",h]]);export{D as __pageData,f as default};
